package com.chainshield.blockchain.registry;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Component;

import java.io.InputStream;
import java.util.*;

/**
 * Registry holding metadata of all locally deployed testbed smart contracts.
 * Populated automatically from deployed-contracts.json generated by Hardhat deploy.js.
 */
@Component
public class DeployedContractRegistry {

    private static final Logger log = LoggerFactory.getLogger(DeployedContractRegistry.class);

    private final ObjectMapper objectMapper;
    private final Map<String, DeployedContractInfo> contractsByAddress = new HashMap<>();
    private final Map<String, DeployedContractInfo> contractsByType = new HashMap<>();

    private String network = "hardhat";
    private long chainId = 31337L;
    private String deployerAddress = "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266";
    private String testUserAddress = "0x70997970C51812dc3A010C7d01b50e0d17dc79C8";

    public DeployedContractRegistry(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    @PostConstruct
    public void init() {
        loadRegistry();
    }

    public synchronized void loadRegistry() {
        try {
            ClassPathResource resource = new ClassPathResource("deployed-contracts.json");
            if (resource.exists()) {
                try (InputStream is = resource.getInputStream()) {
                    JsonNode root = objectMapper.readTree(is);
                    if (root.has("network")) this.network = root.get("network").asText();
                    if (root.has("chainId")) this.chainId = root.get("chainId").asLong();
                    if (root.has("deployer")) this.deployerAddress = root.get("deployer").asText();
                    if (root.has("testUser")) this.testUserAddress = root.get("testUser").asText();

                    if (root.has("contracts")) {
                        JsonNode contractsNode = root.get("contracts");
                        contractsNode.fields().forEachRemaining(entry -> {
                            JsonNode c = entry.getValue();
                            String address = c.get("address").asText();
                            String name = c.has("name") ? c.get("name").asText() : entry.getKey();
                            String symbol = c.has("symbol") ? c.get("symbol").asText() : "";
                            int decimals = c.has("decimals") ? c.get("decimals").asInt() : 18;
                            String type = c.has("type") ? c.get("type").asText() : "UNKNOWN";
                            String expectedRisk = c.has("expectedRisk") ? c.get("expectedRisk").asText() : "LOW";
                            String description = c.has("description") ? c.get("description").asText() : "";

                            DeployedContractInfo info = new DeployedContractInfo(
                                    address, name, symbol, decimals, type, expectedRisk, description
                            );

                            contractsByAddress.put(address.toLowerCase(Locale.ROOT), info);
                            contractsByType.put(type.toUpperCase(Locale.ROOT), info);
                        });
                    }
                    log.info("Loaded {} deployed testbed contracts from deployed-contracts.json", contractsByAddress.size());
                    return;
                }
            }
        } catch (Exception e) {
            log.warn("Could not read deployed-contracts.json from classpath: {}. Using default testbed mapping.", e.getMessage());
        }

        // Hardhat deterministic defaults if file not yet loaded
        registerDefaultContracts();
    }

    private void registerDefaultContracts() {
        register(new DeployedContractInfo(
                "0x5FbDB2315678afecb367f032d93F642f64180aa3",
                "ShieldToken", "SHLD", 18,
                "BENIGN_ERC20", "LOW",
                "Audited benign standard ERC-20 reference token."
        ));
        register(new DeployedContractInfo(
                "0x9fE46736679d2D9a65F0992F2272dE9f3c7FA6e0",
                "SafeVault", "VAULT", 18,
                "BENIGN_VAULT", "LOW",
                "Reentrancy-guarded escrow contract with transparent accounting."
        ));
        register(new DeployedContractInfo(
                "0xCf7Ed3AccA5a467e9e704C703E8D87F634fB0Fc9",
                "TrapToken", "TRAP", 18,
                "MALICIOUS_HONEYPOT", "CRITICAL",
                "Honeypot token with trading locked and unilateral owner controls."
        ));
        register(new DeployedContractInfo(
                "0x5FC8d32690cc91D4c39d9d3abcBD16989F875707",
                "DangerousApprovalSpender", "DRAIN", 0,
                "MALICIOUS_APPROVAL_SPENDER", "HIGH",
                "Contract designed to exploit unlimited token allowances and drain funds."
        ));
    }

    private void register(DeployedContractInfo info) {
        contractsByAddress.put(info.address().toLowerCase(Locale.ROOT), info);
        contractsByType.put(info.type().toUpperCase(Locale.ROOT), info);
    }

    public Optional<DeployedContractInfo> findByAddress(String address) {
        if (address == null) return Optional.empty();
        return Optional.ofNullable(contractsByAddress.get(address.trim().toLowerCase(Locale.ROOT)));
    }

    public Optional<DeployedContractInfo> findByType(String type) {
        if (type == null) return Optional.empty();
        return Optional.ofNullable(contractsByType.get(type.trim().toUpperCase(Locale.ROOT)));
    }

    public List<DeployedContractInfo> getAllContracts() {
        return new ArrayList<>(contractsByAddress.values());
    }

    public boolean isKnownContract(String address) {
        return findByAddress(address).isPresent();
    }

    public boolean isHoneypot(String address) {
        return findByAddress(address).map(c -> "MALICIOUS_HONEYPOT".equals(c.type())).orElse(false);
    }

    public boolean isDangerousSpender(String address) {
        return findByAddress(address).map(c -> "MALICIOUS_APPROVAL_SPENDER".equals(c.type())).orElse(false);
    }

    public Optional<String> getAddressForContract(String nameOrType) {
        if (nameOrType == null) return Optional.empty();
        for (DeployedContractInfo info : contractsByAddress.values()) {
            if (info.name().equalsIgnoreCase(nameOrType) || info.type().equalsIgnoreCase(nameOrType)) {
                return Optional.of(info.address());
            }
        }
        return Optional.empty();
    }

    public String getNetwork() { return network; }
    public long getChainId() { return chainId; }
    public String getDeployerAddress() { return deployerAddress; }
    public String getTestUserAddress() { return testUserAddress; }

    public record DeployedContractInfo(
            String address,
            String name,
            String symbol,
            int decimals,
            String type,
            String expectedRisk,
            String description
    ) {}
}
